/bin/bash -lc "python3 - <<'PY'
import json
START=155811822; END=155812122
TARGETS=['Pan_troglodytes','Macaca_mulatta','Pan_paniscus','Indri_indri','Semnopithecus_johnii','Ailuropoda_melanoleuca','Delphinapterus_leucas']
def revcomp(seq): return seq.translate(str.maketrans('ACGTNacgtn','TGCANtgcan'))[::-1].upper()
def lev(a,b):
 prev=list(range(len(b)+1))
 for i,ca in enumerate(a,1):
  cur=[i]
  for j,cb in enumerate(b,1):
   cur.append(min(prev[j]+1,cur[j-1]+1,prev[j-1]+(ca"'!=cb)))
  prev=cur
 return prev[-1]
def parse(maf):
 rows={}
 for line in maf.replace('"';','\\n').splitlines():
  line=line.strip()
  if line.startswith('s '):
   p=line.split(); rows[p[1]]={'start':int(p[2]),'size':int(p[3]),'strand':p[4],'text':p[6]}
 return rows
maf=json.load(open('cactus447_region.json'))['cactus447way'][0]['mafBlock']
rows=parse(maf); h=rows['hg38.chr7']; pos=h['start']; selected=[]
for i,b in enumerate(h['text']):
 if b"'!='"'-':
  if START<=pos<END: selected.append(i)
  pos+=1
first,last=selected[0], selected[-1]
allcols=list(range(first,last+1))
human=revcomp(''.join(h['text'][i] for i in allcols).replace('-',''))
print('human len',len(human))
for include_mode, cols in [('humanbase',selected),('bounded',allcols)]:
 vals=[]
 print(include_mode, 'cols', len(cols), 'human gaps', sum(1 for i in cols if h['text'][i]=='-'))
 for target in TARGETS:
  src,row=next((src,row) for src,row in rows.items() if src.split('.')[0]==target)
  seq=revcomp(''.join(row['text'][i] for i in cols).replace('-',''))
  vals.append(lev(human,seq))
  print(target, len(seq), lev(human,seq), 'insertBasesVsHuman' if include_mode=='bounded' else '', len(seq)-300)
 print(','.join(map(str,vals)))
PY"
